public void updateDept(DeptSaveReqVO updateReqVO) {
        if (updateReqVO.getParentId() == null) {
            updateReqVO.setParentId(DeptDO.PARENT_ID_ROOT);
        }
        // 校验自己存在
        validateDeptExists(updateReqVO.getId());
        // 校验父部门的有效性
        validateParentDept(updateReqVO.getId(), updateReqVO.getParentId());
        // 校验部门名的唯一性
        validateDeptNameUnique(updateReqVO.getId(), updateReqVO.getParentId(), updateReqVO.getName());

        // 更新部门
        DeptDO updateObj = BeanUtils.toBean(updateReqVO, DeptDO.class);
        deptMapper.updateById(updateObj);
    }

public void updateSpu(ProductSpuSaveReqVO updateReqVO) {
        // 校验 SPU 是否存在
        ProductSpuDO spu = validateSpuExists(updateReqVO.getId());
        // 校验分类、品牌
        validateCategory(updateReqVO.getCategoryId());
        brandService.validateProductBrand(updateReqVO.getBrandId());
        // 校验SKU
        List<ProductSkuSaveReqVO> skuSaveReqList = updateReqVO.getSkus();
        productSkuService.validateSkuList(skuSaveReqList, updateReqVO.getSpecType());

        // 更新 SPU
        ProductSpuDO updateObj = BeanUtils.toBean(updateReqVO, ProductSpuDO.class).setStatus(spu.getStatus());
        initSpuFromSkus(updateObj, skuSaveReqList);
        productSpuMapper.updateById(updateObj);
        // 批量更新 SKU
        productSkuService.updateSkuList(updateObj.getId(), updateReqVO.getSkus());
    }

public void updatePropertyValue(ProductPropertyValueSaveReqVO updateReqVO) {
        validatePropertyValueExists(updateReqVO.getId());
        // 校验名字唯一
        ProductPropertyValueDO value = productPropertyValueMapper.selectByName
                (updateReqVO.getPropertyId(), updateReqVO.getName());
        if (value != null && !value.getId().equals(updateReqVO.getId())) {
            throw exception(PROPERTY_VALUE_EXISTS);
        }

        // 更新
        ProductPropertyValueDO updateObj = BeanUtils.toBean(updateReqVO, ProductPropertyValueDO.class);
        productPropertyValueMapper.updateById(updateObj);
        // 更新 sku 相关属性
        productSkuService.updateSkuPropertyValue(updateObj.getId(), updateObj.getName());
    }

public void updateProperty(ProductPropertySaveReqVO updateReqVO) {
        validatePropertyExists(updateReqVO.getId());
        // 校验名字重复
        ProductPropertyDO property = productPropertyMapper.selectByName(updateReqVO.getName());
        if (property != null &&
                ObjUtil.notEqual(property.getId(), updateReqVO.getId())) {
            throw exception(PROPERTY_EXISTS);
        }

        // 更新
        ProductPropertyDO updateObj = BeanUtils.toBean(updateReqVO, ProductPropertyDO.class);
        productPropertyMapper.updateById(updateObj);
        // 更新 sku 相关属性
        productSkuService.updateSkuProperty(updateObj.getId(), updateObj.getName());
    }

public void updateCategory(ProductCategorySaveReqVO updateReqVO) {
        // 校验分类是否存在
        validateProductCategoryExists(updateReqVO.getId());
        // 校验父分类存在
        validateParentProductCategory(updateReqVO.getParentId());

        // 更新
        ProductCategoryDO updateObj = BeanUtils.toBean(updateReqVO, ProductCategoryDO.class);
        productCategoryMapper.updateById(updateObj);
    }

public void updateWorkItem(PmsWorkItemSaveReqVO saveReqVO, Long userId) {
        // 1.1 校验工作项存在
        PmsWorkItemDO workItem = validateWorkItemExists(saveReqVO.getId());
        // 1.2 校验工作项处于正常状态
        validateActiveWorkItem(workItem);
        // 1.3 校验项目可编辑
        PmsProjectDO project = projectMemberService.validateProjectWritable(workItem.getProjectId(), userId);
        // 1.4 校验项目处于进行中
        validateActiveProject(project);
        // 1.5 校验工作项关联关系
        validateWorkItemRelations(workItem.getId(), project, workItem.getType(), saveReqVO, userId);
        // 1.6 校验工作项参与人
        validateWorkItemMembers(project.getId(), saveReqVO, userId);
        // 1.7 校验工作项标签
        workItemLabelService.validateWorkItemLabelIds(saveReqVO.getLabelIds());
        Set<Long> oldMemberUserIds = convertSet(workItemMemberMapper.selectListByWorkItemIds(
                Collections.singleton(workItem.getId())), PmsWorkItemMemberDO::getUserId);
        Set<Long> newMemberUserIds = getMemberUserIds(saveReqVO, userId);

        // 2. 更新工作项业务字段，不允许表单修改类型和生命周期状态
        PmsWorkItemDO updateObj = BeanUtils.toBean(saveReqVO, PmsWorkItemDO.class)
                .setProjectId(null).setType(null).setName(saveReqVO.getName().trim());
        workItemMapper.updateForEdit(updateObj);

        // 3.1 重建工作项参与人关系
        workItemMemberMapper.deleteByWorkItemId(workItem.getId());
        saveWorkItemMembers(workItem.getId(), project.getId(), newMemberUserIds);
        // 3.2 按字段记录工作项更新动态
        workItemActivityService.createWorkItemUpdateActivities(workItem, updateObj,
                oldMemberUserIds, newMemberUserIds, userId);

        // 4. 负责人发生变化时通知新负责人
        if (ObjectUtil.notEqual(workItem.getAssigneeUserId(), saveReqVO.getAssigneeUserId())) {
            sendWorkItemAssignedNotify(saveReqVO.getAssigneeUserId(), userId, project.getId(),
                    project.getName(), workItem.getSerialNumber(), updateObj.getName());
        }
    }

public void updateWorkItemWorkLog(PmsWorkItemWorkLogSaveReqVO saveReqVO, Long userId) {
        // 1.1 校验工时记录存在
        PmsWorkItemWorkLogDO workLog = validateWorkLogExists(saveReqVO.getId());
        // 1.2 校验工时记录属于请求工作项
        if (ObjectUtil.notEqual(workLog.getWorkItemId(), saveReqVO.getWorkItemId())) {
            throw exception(WORK_ITEM_WORK_LOG_INVALID);
        }
        // 1.3 校验工作项可编辑
        PmsWorkItemDO workItem = workItemService.getWritableWorkItem(workLog.getWorkItemId(), userId);

        // 2.1 更新投入工时和说明
        workLogMapper.updateForEdit(BeanUtils.toBean(saveReqVO, PmsWorkItemWorkLogDO.class)
                .setId(workLog.getId()).setDescription(StrUtil.trim(saveReqVO.getDescription())));
        // 2.2 记录工时更新动态
        workItemActivityService.createWorkItemActivity(
                workItem.getProjectId(), workItem.getId(), userId, WORK_LOG_UPDATED);
    }

public void updateWorkItemLabel(PmsWorkItemLabelSaveReqVO saveReqVO) {
        // 1. 校验标签存在
        validateLabelExists(saveReqVO.getId());

        // 2. 更新标签
        labelMapper.updateById(BeanUtils.toBean(saveReqVO, PmsWorkItemLabelDO.class)
                .setName(StrUtil.trim(saveReqVO.getName())).setColor(StrUtil.trim(saveReqVO.getColor())));
    }

public void updateWorkItemComment(PmsWorkItemCommentSaveReqVO saveReqVO, Long userId) {
        // 1.1 校验评论存在
        PmsWorkItemCommentDO comment = validateCommentExists(saveReqVO.getId());
        // 1.2 校验工作项可编辑
        PmsWorkItemDO workItem = workItemService.getWritableWorkItem(comment.getWorkItemId(), userId);
        // 1.3 校验评论属于当前用户
        validateCommentOwner(comment, userId);

        // 2.1 更新评论内容
        commentMapper.updateById(BeanUtils.toBean(saveReqVO, PmsWorkItemCommentDO.class).setId(comment.getId()));
        // 2.2 记录评论更新动态
        workItemActivityService.createWorkItemActivity(
                workItem.getProjectId(), workItem.getId(), userId, COMMENT_UPDATED);
    }

public void updateProject(PmsProjectSaveReqVO saveReqVO, Long userId) {
        // 1.1 校验项目存在
        PmsProjectDO project = validateProjectExists(saveReqVO.getId());
        // 1.2 校验项目处于进行中
        validateActiveProject(project);
        // 1.3 校验当前用户可以管理项目
        validateProjectManagerPermission(saveReqVO.getId(), userId);

        // 2. 更新项目基本信息
        PmsProjectDO updateObj = BeanUtils.toBean(saveReqVO, PmsProjectDO.class)
                .setType(null);
        projectMapper.updateById(updateObj);
    }

public void updateProjectTemplate(PmsProjectTemplateSaveReqVO updateReqVO) {
        // 1. 校验模板存在、名称和协作配置
        validateProjectTemplateExists(updateReqVO.getId());
        validateProjectTemplateNameDuplicate(updateReqVO.getName(), updateReqVO.getProjectType(), updateReqVO.getId());
        validateProjectTemplateConfig(updateReqVO);

        // 2. 更新项目模板
        projectTemplateMapper.updateById(buildProjectTemplateDO(updateReqVO));
    }

public void updateProjectGroup(PmsProjectGroupSaveReqVO updateReqVO, Long userId) {
        // 1.1 校验分组存在
        PmsProjectGroupDO group = validateProjectGroupExists(updateReqVO.getId(), userId);
        // 1.2 校验分组为自定义分组
        if (ObjectUtil.notEqual(PmsProjectGroupTypeEnum.CUSTOM.getType(), group.getType())) {
            throw exception(PROJECT_GROUP_DEFAULT_CANNOT_MODIFY);
        }
        // 1.3 校验分组名称唯一
        validateProjectGroupNameDuplicate(userId, updateReqVO.getName(), updateReqVO.getId());

        // 2. 更新分组名称
        projectGroupMapper.updateById(BeanUtils.toBean(updateReqVO, PmsProjectGroupDO.class)
                .setUserId(null).setSort(null).setType(null));
    }

public void updateProjectAnnouncement(PmsProjectAnnouncementSaveReqVO saveReqVO, Long userId) {
        // 1.1 校验公告存在
        PmsProjectAnnouncementDO announcement = validateAnnouncementExists(saveReqVO.getId());
        // 1.2 校验公告属于请求项目
        if (ObjectUtil.notEqual(announcement.getProjectId(), saveReqVO.getProjectId())) {
            throw exception(PROJECT_ANNOUNCEMENT_NOT_EXISTS);
        }
        // 1.3 校验项目编辑权限
        projectMemberService.validateProjectWritable(announcement.getProjectId(), userId);

        // 2. 更新公告
        announcementMapper.updateById(BeanUtils.toBean(saveReqVO, PmsProjectAnnouncementDO.class));
